package notification.core.recipient;import notification.core.recipient.Recipient;/** * SMS-specific recipient. */public class SmsRecipient implements Recipient {    private final String phoneNumber;    private final String language;    public SmsRecipient(            String phoneNumber,            String language) {        this.phoneNumber = phoneNumber;        this.language = language;    }    public String getPhoneNumber() {        return phoneNumber;    }    @Override    public String id() {        return phoneNumber;    }    @Override    public String language() {        return language;    }}